<?php
require 'includes/auth.php';
require 'config/database.php';
$id=$_GET['id']??0;
$stmt=$pdo->prepare("SELECT * FROM ventas WHERE id=?"); $stmt->execute([$id]); $venta=$stmt->fetch();
if(!$venta) die('No encontrada');
$det=$pdo->prepare("SELECT * FROM venta_detalle WHERE venta_id=?"); $det->execute([$id]); $detalles=$det->fetchAll();
if($_SERVER['REQUEST_METHOD']=='POST'){
 $numero=$_POST['numero_ticket']; $fecha=$_POST['fecha']; $pista=$_POST['pista']??null;
 $placa=strtoupper(trim($_POST['placa'])); $tipo_veh=$_POST['tipo_vehiculo']; $valor_total=(int)$_POST['valor_total']; $obs=$_POST['observaciones']??null;
 $servicios=$_POST['servicios']??[];
 $pdo->beginTransaction();
 try{
  $pdo->prepare("UPDATE ventas SET numero_ticket=?, fecha=?, pista=?, placa=?, tipo_vehiculo=?, valor_total=?, observaciones=? WHERE id=?")->execute([$numero,$fecha,$pista,$placa,$tipo_veh,$valor_total,$obs,$id]);
  $pdo->prepare("DELETE FROM venta_detalle WHERE venta_id=?")->execute([$id]);
  $stmtD=$pdo->prepare("INSERT INTO venta_detalle (venta_id, servicio, precio) VALUES (?,?,?)");
  foreach($servicios as $s){ $stmtD->execute([$id, $s['nombre'], $s['precio']]); }
  $pdo->commit(); header('Location: ventas_hoy.php?fecha='.$fecha); exit;
 } catch(Exception $e){ $pdo->rollBack(); die($e->getMessage()); }
}
require 'includes/header.php';
?>
<div class="mt-3"><h5 class="fw-bold">Editar #<?= htmlspecialchars($venta['numero_ticket']) ?></h5>
<form id="formVenta" method="POST" class="card card-rio p-3 mt-3">
<div class="row g-2">
<div class="col-6"><label class="small fw-bold">Nº Ticket</label><input name="numero_ticket" class="form-control form-control-lg" value="<?= htmlspecialchars($venta['numero_ticket']) ?>" required></div>
<div class="col-6"><label class="small fw-bold">Fecha</label><input type="date" name="fecha" class="form-control form-control-lg" value="<?= $venta['fecha'] ?>" required></div>
<div class="col-4"><label class="small">Pista</label><select name="pista" class="form-select"><option value="">-</option><?php for($i=1;$i<=6;$i++): ?><option <?= $venta['pista']==$i?'selected':'' ?>><?= $i ?></option><?php endfor; ?></select></div>
<div class="col-8"><label class="small fw-bold">Placa</label><input name="placa" id="placa" class="form-control form-control-lg text-uppercase" value="<?= htmlspecialchars($venta['placa']) ?>" required></div>
<div class="col-12 mt-3"><label class="small fw-bold">Tipo Vehículo</label><div class="d-flex flex-wrap gap-2 mt-1" id="chipsVehiculo"><?php $chips=['AUTOMOVIL','CAMIONETA','MOTO','MOTO_ALTO','BICICLETA','CAMION_PEQ','CAMION_GDE','ALFOMBRA','PARQUEADERO']; foreach($chips as $c): ?><button type="button" class="chip <?= $venta['tipo_vehiculo']==$c?'active':'' ?>" data-v="<?= $c ?>"><?= $c ?></button><?php endforeach; ?></div><input type="hidden" name="tipo_vehiculo" id="tipo_vehiculo" value="<?= $venta['tipo_vehiculo'] ?>" required></div>
<div class="col-12 mt-3" id="serviciosContainer"><label class="small fw-bold">Servicios</label><div id="listaServicios" class="d-flex flex-column gap-2 mt-2"></div><div class="card bg-light p-2 mt-3" id="resumenServ"><div id="listaResumen" class="small"></div><div class="d-flex justify-content-between mt-2 border-top pt-2"><b>Total:</b><b id="totalPreview" style="color:#1e40af; font-size:1.3rem">$0</b></div></div></div>
<div class="col-12 mt-3"><label class="small fw-bold">Valor Total</label><div class="input-group input-group-lg"><span class="input-group-text">$</span><input name="valor_total" id="valor_total" type="number" class="form-control fw-bold" value="<?= $venta['valor_total'] ?>" required></div></div>
<div class="col-12"><label class="small">Observaciones</label><textarea name="observaciones" class="form-control" rows="2"><?= htmlspecialchars($venta['observaciones']) ?></textarea></div>
<div class="col-12 mt-2"><button class="btn btn-rio w-100">GUARDAR CAMBIOS</button><a href="ventas_hoy.php?fecha=<?= $venta['fecha'] ?>" class="btn btn-light w-100 mt-2">Cancelar</a></div>
</div></form></div>
<script>
const preciosBase = {"Lavado General": {AUTOMOVIL:25000, CAMIONETA:30000},"Lavado Motor": {AUTOMOVIL:25000, CAMIONETA:30000},"Lavado Chasis": {AUTOMOVIL:25000, CAMIONETA:30000},"Adicional Camioneta": {CAMIONETA:6000},"Grafitado": {AUTOMOVIL:22000, CAMIONETA:25000},"Restauración Partes Negras": {AUTOMOVIL:25000, CAMIONETA:30000},"Encerado Manual": {AUTOMOVIL:68000, CAMIONETA:79000},"Polichado a Máquina": {AUTOMOVIL:150000, CAMIONETA:180000},"Lavado de Tapicería": {AUTOMOVIL:190000, CAMIONETA:230000},"Lavado de Cojinería": {AUTOMOVIL:110000, CAMIONETA:121000},"Lavado Alfombra Auto": {AUTOMOVIL:83000, CAMIONETA:88000},"Lavado Puertas y Tablero": {AUTOMOVIL:50000, CAMIONETA:56000},"Lavado de Techo": {AUTOMOVIL:58000, CAMIONETA:64000},"Cristalizado Rio 3 Pasos 3M": {AUTOMOVIL:260000, CAMIONETA:285000},"COMBO RIO 1": {AUTOMOVIL:85000, CAMIONETA:98000},"COMBO RIO 2": {AUTOMOVIL:145000, CAMIONETA:175000},"COMBO RIO 3": {AUTOMOVIL:300000, CAMIONETA:350000},"COMBO RIO 4": {AUTOMOVIL:375000, CAMIONETA:450000},"COMBO RIO 5": {AUTOMOVIL:330000, CAMIONETA:365000},"COMBO LAVADO FRR": {AUTOMOVIL:160000, CAMIONETA:160000},"Lavado y Pulida Motos": {MOTO:20000, MOTO_ALTO:20000},"Alto Cilindraje": {MOTO_ALTO:25000, MOTO:25000},"Alfombra Pequeña": {AUTOMOVIL:36000, CAMIONETA:36000, ALFOMBRA:36000, DEFAULT:36000},"Alfombra Mediana": {AUTOMOVIL:43000, CAMIONETA:43000, ALFOMBRA:43000, DEFAULT:43000},"Alfombra Grande": {AUTOMOVIL:46000, CAMIONETA:46000, ALFOMBRA:46000, DEFAULT:46000},"Bicicleta": {BICICLETA:10000, DEFAULT:10000},"Lavado Camión Pequeño": {CAMION_PEQ:100000, DEFAULT:100000},"Lavado Camión Grande": {CAMION_GDE:110000, DEFAULT:110000},"Parqueadero": {PARQUEADERO:8000, DEFAULT:8000},"Parqueadero X Horas": {PARQUEADERO:4000, DEFAULT:4000}};
const serviciosPorVehiculo = {AUTOMOVIL: ["Lavado General","Lavado Motor","Lavado Chasis","Grafitado","Restauración Partes Negras","Encerado Manual","Polichado a Máquina","Lavado de Tapicería","Lavado de Cojinería","Lavado Alfombra Auto","Lavado Puertas y Tablero","Lavado de Techo","Cristalizado Rio 3 Pasos 3M","COMBO RIO 1","COMBO RIO 2","COMBO RIO 3","COMBO RIO 4","COMBO RIO 5","COMBO LAVADO FRR","Alfombra Pequeña","Alfombra Mediana","Alfombra Grande"],CAMIONETA: ["Lavado General","Lavado Motor","Lavado Chasis","Adicional Camioneta","Grafitado","Restauración Partes Negras","Encerado Manual","Polichado a Máquina","Lavado de Tapicería","Lavado de Cojinería","Lavado Alfombra Auto","Lavado Puertas y Tablero","Lavado de Techo","Cristalizado Rio 3 Pasos 3M","COMBO RIO 1","COMBO RIO 2","COMBO RIO 3","COMBO RIO 4","COMBO RIO 5","COMBO LAVADO FRR","Alfombra Pequeña","Alfombra Mediana","Alfombra Grande"],MOTO: ["Lavado y Pulida Motos","Grafitado","Encerado Manual"],MOTO_ALTO: ["Lavado y Pulida Motos","Alto Cilindraje","Grafitado","Encerado Manual"],BICICLETA: ["Bicicleta"],CAMION_PEQ: ["Lavado Camión Pequeño"],CAMION_GDE: ["Lavado Camión Grande"],ALFOMBRA: ["Alfombra Pequeña","Alfombra Mediana","Alfombra Grande","Lavado Alfombra Auto"],PARQUEADERO: ["Parqueadero","Parqueadero X Horas"]};
let vehSel="<?= $venta['tipo_vehiculo'] ?>"; let existentes=<?= json_encode($detalles) ?>; let seleccionados=existentes.map(d=>({serv:d.servicio, precio:parseInt(d.precio)}));
function getPrecio(serv, veh){ let p=preciosBase[serv]; if(!p) return 0; return p[veh] || p.DEFAULT || p.AUTOMOVIL || p.CAMIONETA || 0; }
document.querySelectorAll('#chipsVehiculo .chip').forEach(c=>{ c.addEventListener('click', ()=>{ document.querySelectorAll('#chipsVehiculo .chip').forEach(x=>x.classList.remove('active')); c.classList.add('active'); vehSel=c.dataset.v; document.getElementById('tipo_vehiculo').value=vehSel; renderServicios(); }); });
function renderServicios(){ const lista=serviciosPorVehiculo[vehSel]||[]; const cont=document.getElementById('listaServicios'); cont.innerHTML=''; lista.forEach(serv=>{ let precio=getPrecio(serv, vehSel); let checked=seleccionados.some(s=>s.serv===serv); let div=document.createElement('div'); div.className='serv-card'+(checked?' checked':''); div.innerHTML=`<div class="d-flex align-items-center gap-2"><input type="checkbox" class="form-check-input m-0" style="width:20px;height:20px" data-serv="${serv}" data-precio="${precio}" ${checked?'checked':''}><span class="fw-semibold small">${serv}</span></div><b class="small" style="color:#1e40af">$${precio.toLocaleString('es-CO')}</b>`; div.addEventListener('click', (e)=>{ if(e.target.type!=='checkbox'){ let cb=div.querySelector('input'); cb.checked=!cb.checked; } toggleServ(div.querySelector('input')); }); div.querySelector('input').addEventListener('change', function(){ toggleServ(this); }); cont.appendChild(div); }); updateResumen(); }
function toggleServ(cb){ let serv=cb.dataset.serv; let precio=parseInt(cb.dataset.precio); let card=cb.closest('.serv-card'); if(cb.checked){ card.classList.add('checked'); if(!seleccionados.some(s=>s.serv===serv)) seleccionados.push({serv, precio}); } else { card.classList.remove('checked'); seleccionados=seleccionados.filter(s=>s.serv!==serv); } updateResumen(); }
function updateResumen(){ let total=seleccionados.reduce((a,b)=>a+b.precio,0); document.getElementById('valor_total').value=total; document.getElementById('listaResumen').innerHTML=seleccionados.map(s=>`${s.serv} - $${s.precio.toLocaleString('es-CO')}`).join('<br>'); document.getElementById('totalPreview').innerText='$'+total.toLocaleString('es-CO'); document.querySelectorAll('.hidden-serv').forEach(e=>e.remove()); let form=document.getElementById('formVenta'); seleccionados.forEach((s,i)=>{ let inp=document.createElement('input'); inp.type='hidden'; inp.name=`servicios[${i}][nombre]`; inp.value=s.serv; inp.className='hidden-serv'; form.appendChild(inp); let inp2=document.createElement('input'); inp2.type='hidden'; inp2.name=`servicios[${i}][precio]`; inp2.value=s.precio; inp2.className='hidden-serv'; form.appendChild(inp2); }); }
renderServicios(); updateResumen();
</script>
<?php require 'includes/footer.php'; ?>
